    94	/** Remove live approval mutations before a historical result is persisted. */
    95	export function displaySafeMcpAppResult(value: unknown): unknown {
    96		if (Array.isArray(value)) return value.map(displaySafeMcpAppResult);
    97		if (!isRecord(value)) return value;
    98		return Object.fromEntries(
    99			Object.entries(value).map(([key, inner]) => {
   100				if (key === "actions" && Array.isArray(inner)) {
   101					return [
   102						key,
   103						inner
   104							.filter(
   105								(action) =>
   106									!isRecord(action) || action.tool !== "resolve_lobu_approval",
   107							)
   108							.map(displaySafeMcpAppResult),
   109					];
   110				}
   111				return [key, displaySafeMcpAppResult(inner)];
   112			}),
   113		);
   114	}
   115	
   116	/** Accept only small primitive interaction state; result data never flows here. */
   117	export function boundedMcpAppViewState(value: unknown): McpAppViewState {
   118		if (!isRecord(value)) return {};
   119		const state: McpAppViewState = {};
   120		for (const [key, inner] of Object.entries(value).slice(
   121			0,
   122			VIEW_STATE_MAX_KEYS,
   123		)) {
   124			if (!key || key.length > VIEW_STATE_KEY_MAX_LENGTH) continue;
   125			if (
   126				typeof inner !== "boolean" &&
   127				!(typeof inner === "number" && Number.isFinite(inner)) &&
   128				!(
   129					typeof inner === "string" &&
   130					inner.length <= VIEW_STATE_STRING_MAX_LENGTH
   131				)
   132			) {
   133				continue;
   134			}
   135			const candidate = { ...state, [key]: inner as boolean | number | string };
   136			if (Buffer.byteLength(JSON.stringify(candidate), "utf8") > VIEW_STATE_MAX_BYTES)
   137				break;
   138			state[key] = inner as boolean | number | string;
   139		}
   140		return state;
   141	}
   142	
   143	function parseSnapshot(body: string): SnapshotPayload | null {
   144		try {
   145			const parsed: unknown = JSON.parse(decrypt(body));
   146			if (
   147				!isRecord(parsed) ||
   148				parsed.version !== 1 ||
   149				typeof parsed.toolName !== "string" ||
   150				!isRecord(parsed.data)
   151			) {
   152				return null;
   153			}
   154			return {
   155				version: 1,
   156				toolName: parsed.toolName,
   157				data: parsed.data,
   158				viewState: boundedMcpAppViewState(parsed.viewState),
   159				...(typeof parsed.bindingKey === "string" &&
   160					/^[a-f0-9]{64}$/.test(parsed.bindingKey)
   161					? { bindingKey: parsed.bindingKey }
   162					: {}),
   163			};
   164		} catch {
   165			return null;
   166		}
   167	}
   168	
   169	function serializeSnapshot(payload: SnapshotPayload): {
   170		body: string;
   171		plaintextBytes: number;
   172	} | null {
   173		const plaintext = JSON.stringify(payload);
   174		const plaintextBytes = Buffer.byteLength(plaintext, "utf8");
   175		if (plaintextBytes === 0 || plaintextBytes > MCP_APP_RESULT_MAX_BYTES)
   176			return null;
   177		return { body: encrypt(plaintext), plaintextBytes };
   178	}
   179	
   180	export async function storeMcpAppResultSnapshot(args: {
   181		ctx: ToolContext;
   182		toolCallId: unknown;
   183		bindingCapability?: unknown;
   184		toolName: string;
   185		data: UnknownRecord;
   186	}): Promise<boolean> {
   187		const identity = snapshotIdentity(args.ctx, args.toolCallId);
   188		if (
   189			!identity ||
   190			!args.toolName ||
   191			args.toolName.length > TOOL_NAME_MAX_LENGTH
   192		)
   193			return false;
   194		const bindingCapability = normalizeMcpAppToolCallId(args.bindingCapability);
   195		const data = displaySafeMcpAppResult(args.data);
   196		if (!isRecord(data)) return false;
   197		const serialized = serializeSnapshot({
   198			version: 1,
   199			toolName: args.toolName,
   200			data,
   201			viewState: {},
   202			...(bindingCapability
   203				? { bindingKey: hashIdentity(bindingCapability) }
   204				: {}),
   205		});
   206		if (!serialized) return false;
   207	
   208		const sql = getDb();
   209		const collided = await sql.begin(async (tx) => {
   210			const [stored] = await tx<{ collided: boolean }>`
   211				INSERT INTO public.mcp_app_result_snapshots (
   212					organization_id, client_id, user_id, conversation_key,
   213					tool_call_key, tool_name, body, plaintext_bytes, expires_at
   214				) VALUES (
   215					${identity.organizationId}, ${identity.clientId}, ${identity.userId},
   216					${identity.conversationKey}, ${identity.toolCallKey}, ${args.toolName},
   217					${serialized.body}, ${serialized.plaintextBytes},
   218					now() + (${MCP_APP_RESULT_RETENTION_DAYS} * interval '1 day')
   219				)
   220				ON CONFLICT (
   221					organization_id, client_id, user_id, conversation_key, tool_call_key
   222				) DO UPDATE SET
   223					-- A host request ID is not guaranteed to be unique forever. Never let a
   224					-- collision replace the historical card with a different result.
   225					expires_at = now(),
   226					updated_at = now()
   227				RETURNING expires_at <= now() AS collided
   228			`;
   229			await tx`
   230				DELETE FROM public.mcp_app_result_snapshots snapshot
   231				WHERE snapshot.organization_id = ${identity.organizationId}
   232					AND snapshot.client_id = ${identity.clientId}
   233					AND snapshot.user_id = ${identity.userId}
   234					AND snapshot.conversation_key = ${identity.conversationKey}
   235					AND snapshot.tool_call_key NOT IN (
   236						SELECT kept.tool_call_key
   237						FROM public.mcp_app_result_snapshots kept
   238						WHERE kept.organization_id = ${identity.organizationId}
   239							AND kept.client_id = ${identity.clientId}
   240							AND kept.user_id = ${identity.userId}
   241							AND kept.conversation_key = ${identity.conversationKey}
   242						ORDER BY kept.updated_at DESC, kept.tool_call_key
   243						LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
   244					)
   245			`;
   246			return stored?.collided === true;
   247		});
   248		if (collided) {
   249			logger.warn(
   250				{ toolName: args.toolName },
   251				"MCP App result snapshot key collision; historical restore disabled",
   252			);
   253		}
   254		return !collided;
   255	}
