import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	close: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() {
			return { isError: false };
		}
	},
	PostMessageTransport: class {
		close = bridge.close;
	},
}));

type CompatParent = EventTarget & {
	location: { origin: string };
	openai?: unknown;
};

const parentDescriptor = Object.getOwnPropertyDescriptor(window, "parent");
const openaiDescriptor = Object.getOwnPropertyDescriptor(window, "openai");

function restore(name: "parent" | "openai", descriptor: PropertyDescriptor | undefined) {
	if (descriptor) Object.defineProperty(window, name, descriptor);
	else Reflect.deleteProperty(window, name);
}

describe("review stale local widget identity", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
		bridge.connect.mockResolvedValue(undefined);
	});

	afterEach(() => {
		restore("parent", parentDescriptor);
		restore("openai", openaiDescriptor);
	});

	it("does not bind current unpaired output to stale same-target widget identity", async () => {
		Object.defineProperty(window, "openai", {
			configurable: true,
			value: {
				toolOutput: { structuredContent: { title: "Current card" } },
				widgetState: {
					privateContent: {
						lobuViewSnapshot: {
							version: 1,
							data: { title: "Old card" },
							resultIdentity: "old-token",
						},
					},
				},
			},
		});
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: window.location.origin },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
			if (
				name === "restore_lobu_app_result" &&
				args.snapshot_capability === "old-token"
			) {
				return {
					isError: false,
					structuredContent: {
						found: true,
						tool_name: "old_tool",
						data: { title: "Old card" },
						view_state: { "details.open": true },
					},
				};
			}
			return { isError: false, structuredContent: { saved: true } };
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, viewState, toolName } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title}</span>
					<span>open:{String(viewState["details.open"])}</span>
					<span>tool:{toolName ?? "none"}</span>
				</>
			);
		}
		render(
			<Provider devMock={{ title: "Dev" }}>
				<Probe />
			</Provider>,
		);
		expect(await screen.findByText("Current card")).toBeInTheDocument();
		await waitFor(() => expect(bridge.connect).toHaveBeenCalled());
		act(() =>
			window.dispatchEvent(
				new CustomEvent("openai:set_globals", {
					detail: {
						globals: {
							toolResponseMetadata: {
								mcp_tool_result: {
									_meta: {
										"lobu/mcp-app-snapshot-capability": "old-token",
									},
								},
							},
						},
					},
				}),
			),
		);
		await act(() => new Promise((resolve) => window.setTimeout(resolve, 0)));
		expect(bridge.callServerTool).not.toHaveBeenCalledWith({
			name: "restore_lobu_app_result",
			arguments: { snapshot_capability: "old-token" },
		});
		expect(screen.getByText("open:undefined")).toBeInTheDocument();
		expect(screen.getByText("tool:none")).toBeInTheDocument();
	});
});

